local opts = {size = 20, open_mapping = "<C-\\>", hide_numbers = true, start_in_insert = true, insert_mappings = true, direction = "float", float_opts = float_opts, shell = vim.o.shell, close_on_exit = true, persist_size = false, shade_terminals = false}
